window.registerLocale("ko",{ui:{chapter:"브리핑",sound:"사운드",on:"켬",off:"끔",sources:"출처",close:"닫기",tap:"다음",replay:"다시 시작",hint:"탭 / 클릭 / 스페이스",hintEnd:"마지막입니다. 탭하면 처음으로 돌아갑니다",coverKicker:"인시던트 브리핑 · 2026-10",coverTitleA:"한 달에 ",coverTitleB:"15건.",coverSub:"2026년 10월의 15건을 시간 순서로.<br>Apache 부록과 10-23 추가 8장 포함. 탭해서 진행하며 소리가 납니다.<br>10-24에 8장 추가(영어).<br>10/25: +15 scenes (English), including the Tailworm special.",coverStart:"탭하여 시작",coverFoot:"10/25: ConnectWise primary sources verified. Earlier scenes are historical.",drawerTitle:"출처 / SOURCES",drawerFoot:"10/25 sources supersede earlier ConnectWise uncertainty; retrieved after cutoff.",asof:"2026-10-26 21:35 JST"},scenes:{intro:{title:"한 달에, 15건.",lede:"서로 무관해 보이는 사고가 같은 종류의 약점에 반복해서 떨어졌습니다. 순서대로 탭하세요.",points:["15건 중 <b>8건</b>이 npm / pip / 플러그인 / 릴리스 산출물 문제 — 코드가 아니라 <em>배포</em>","ConnectWise now has primary confirmation; see the 10/25 addendum (English).","소리가 납니다. 오른쪽 위에서 끌 수 있습니다"],metric:"사건 · 한 달"},"php-silence":{title:"조용했던 70일.",lede:"보고에서 릴리스까지 70일. 위험한 구간은 공개 이후가 아니라 그 직전이었습니다.",points:["08-01 Calif가 여러 RCE 경로 발견 / 08-11 PHP에 보고","10-20 세부 내용 유출, watchTowr가 RCE 확인","10-21 <b>07:43 UTC</b> 수정 공개 전 공격 시도 관측(Cloudflare)","10-21 14:00 수정판 — 8.5.12 / 8.4.27 / 8.3.36 / 8.2.35"],metric:"보고에서 공개까지 (일)"},zeabur:{title:"평문 관리자 키 하나가 9개 리전을 열었습니다.",lede:"8월에 이어 두 번째. 8월의 교체가 이번에 쓰인 자격증명을 덮지 못했습니다.",points:["10-14 01:36 내부 AWS 키로 진입 / 01:51 시스템 시크릿","12:39부터 전체 서비스의 환경 변수로 확대, <b>865</b>개 DB 서비스에서 명령 실행","원인: 평문·무기한 관리자 자격증명과 공개된 관리 평면","사용자는 모든 환경 변수를 다시 교체해야 합니다(8월에 했더라도)"],metric:"영향받은 DB 서비스"},rankmath:{title:"11시간 동안 공식 다운로드가 오염됐습니다.",lede:"플러그인의 업데이트 경로가 곧 공격 경로입니다. CVSS 9.8.",points:["10-15 20:02 ~ 10-16 07:12 UTC 사이에 받은 <b>3.0.123</b>","<b>CVE-2026-111862</b> / CVSS 9.8 / 3.0.124에서 수정","업데이트는 복구가 아닙니다 — 관리자 계정·추가 파일·예약 작업을 찾으세요","Wordfence가 긴급 방화벽 룰을 앞당겨 배포"],metric:"CVSS · CVE-2026-111862"},teamupdraft:{title:"DB에 있던 키가 수천 사이트의 문이었습니다.",lede:"연결 키는 '정상 서명된 명령'으로 동작합니다. 그래서 기존 보안 수정으로 막히지 않습니다.",points:["고객 DB 유출: 연락처, 해시된 비밀번호, 2단계 인증 설정, <b>세 종류의 연결 키</b>","UpdraftCentral / UpdraftVault / UpdraftClone 키로 악성 플러그인 설치","서명이 진짜였으므로 CVE-2026-10795를 적용한 사이트도 수용","UpdraftPlus 1.26.13 / 2.26.13이 10-18 22:00 BST 이전 연결을 자동 해제"],metric:"악용된 키 종류"},emudhra:{title:"키는 훔쳐지지 않았습니다. 너무 약했습니다.",lede:"P-384 개인 키가 작은 정수였습니다. 하나는 문자 그대로 4이며, 공개 인증서에서 1초 안에 복원됩니다.",points:["<b>8개</b> 중간 CA( TLS 6 + 코드 서명 2), 2025년 4월 키 생성 의식","10-17 18:05 UTC 보고 → 19:45 Chrome이 SPKI 해시로 차단 → 22:59 Firefox 전체 적용","CT는 TLS만 대상입니다. 'CT에 없다'는 코드 서명 2개를 면제하지 않습니다","10-21 Tailscale <b>TS-2026-013</b>: v1.104.2에서 Go 1.27.3 거부 목록 적용"],metric:"문자 그대로의 개인 키"},ovh:{title:"94분 동안 공식 바이너리는 다른 것이었습니다.",lede:"소스와 빌드 체인은 멀쩡했습니다. 깨진 것은 '릴리스 산출물은 교체될 수 없다'는 전제입니다.",points:["10-19 14:47–16:21(UTC+2)에 산출물 교체","대상은 <b>v0.11.0–v0.15.0</b>, 해당 시간대 다운로드만 영향","원인: 저장소가 릴리스 불변성(immutability)을 보장하지 않았음","해결은 설정 하나와 검증 하나: 불변 릴리스 + 서명 확인"],metric:"노출 시간(분)"},oracle:{title:"55건, 최고 7.5 — 함정은 버전 열입니다.",lede:"'영향받는 버전'과 '수정 버전'은 다른 열입니다. 21.0.12.1이 영향판, 수정은 21.0.13.",points:["55건 / 인증 없이 원격 49건 / 최고 CVSS 7.5 / KEV 0건","영향: 8u503, 11.0.32.1, 17.0.20.1, 21.0.12.1, 25.0.4.1, 26.0.2, 27","10-20 수정: <b>8u511 / 11.0.33 / 17.0.21 / 21.0.13 / 25.0.5 / 27.0.1</b>","JDK 26은 수정 없음(26.0.3 부재) — 27로 이동"],metric:"CVE · 무인증 원격 49건"},plex:{title:"4.3짜리 SSRF가 코드 실행의 앞문입니다.",lede:"개별 점수는 평범합니다. CISA의 KEV는 이 네 건이 연결된다고 명시합니다.",points:["10-20 KEV 추가 / 96656과 96654의 기한은 <b>10-23</b>","체인: 아무 X-Plex-Token → SSRF → 플러그인 호출 → 관리자 파일 쓰기 → 시작 시 .so 실행","96651은 KEV에 없지만 <b>PlexOnlineToken</b>을 읽습니다 — 계정 탈취","수정 <b>1.43.3.10861</b>, 현재 최신은 <b>1.43.5.11029</b>; NAS 스토어는 지연"],metric:"KEV 수 · 기한 10-23"},apache:{title:"'Important' 세 건의 결과는 하나 — 남의 데이터.",lede:"Tomcat의 세 건은 방식이 다르고 결과가 같습니다. httpd의 'low'는 7.5입니다. 심각도는 숫자 하나가 아닙니다.",points:["Tomcat: JNDIRealm(비 GSSAPI SASL) 인증 우회 + HTTP/2·AJP 응답 혼선 — <b>11.0.27 / 10.1.61 / 9.0.123</b>","httpd <b>2.4.69</b>: mod_rewrite UAF와 mod_proxy_html 범위 초과 쓰기. Apache는 low, NVD는 7.5","Traffic Server: 요청 밀반입 2건(8.9 / 8.7)","KEV에는 없음 — 공개된 악용이 없다는 뜻이지 안전하다는 뜻이 아닙니다"],metric:"Tomcat 인증 우회 · CVSS 4.0"},"php-race":{title:"수정 6시간 전에 시도가 이미 왔습니다.",lede:"공개 PoC를 기다리면 이미 늦는 종류의 취약점. Node.js도 같은 날 움직였습니다.",points:["<b>07:43 UTC</b> Cloudflare가 수정 공개 전 공격 시도 관측","<b>14:00</b> PHP 수정판 공개 / <b>14:17</b> NVD가 CVE 공개","같은 날: Node.js 22.23.4 / 24.22.1 / 26.12.1 (CA 번들 갱신 포함)","그 24시간 동안 노출됐던 구성은 침해 여부를 따로 확인해야 합니다"],metric:"수정 전 시도까지의 간격"},gitlab:{title:"지난주에 패치했어도 수정판이 아닙니다.",lede:"10월 12일 업데이트는 19.2 이후만 다뤘고, 이번 수정판은 그보다 한 단계 위입니다.",points:["<b>CVE-2026-110264</b> / Onigmo 정수 오버플로 / 무인증 RCE / 7.0(2014) 이후 전부","수정: 19.5.1 / 19.4.3 / 19.3.6 / 19.2.9 / 19.1.9 / 19.0.10 / 18.11.13","10월 12일에 올렸어도 19.2.9 미만이면 다시 해당","공개된 우회책 없음 — 업그레이드가 어렵다면 인터넷 도달성을 제거"],metric:"CVSS · 무인증"},npm:{title:"배포 채널 자체가 공격면이 됐습니다.",lede:"10월의 8건은 코드가 어떻게 전달되는가의 문제입니다. provenance는 '어디서 빌드됐는지'만 말합니다.",points:["LiteLLM 1.107.0: Python 시작 시 탈취, 유사 저장소 <b>Berri-AI</b>에서 빌드","tensorlake@0.5.144: 토큰을 폐기하면 <b>$HOME</b>을 지우는 '인질 토큰'","@subql/common@5.8.3: 설치 시와 import 시 모두 실행","GhostAction: 위조된 security-audit.yml이 <b>345</b>개 저장소의 시크릿과 git 이력을 전송"],metric:"16분 동안 훑은 저장소"},railway:{title:"환경 변수는 원래 비밀을 두는 곳이었습니다.",lede:"'플랫폼 기업을 거쳐 AI 추론 사업자를 노리는 일련의 공격 중 하나' — 벤더 자신의 표현입니다.",points:["고객 환경 변수가 암호화된 채로 읽혔고, 일부는 복호화됐을 수 있음","조사 중 전체 배포 중단, 상류 사업자에 키 선제 폐기 요청","필요한 것은 '샜을지도 모르는 키'가 아니라 <b>전부</b> 교체","SMTP 비밀번호, webhook 서명 키, JWT_SECRET도 환경 변수 안에 있습니다"],metric:"교체할 환경 변수"},bind:{title:"재전송된 패킷 하나가 메모리를 깨뜨린다.",lede:"GSS-TSIG로 서명된 UDP 메시지를 재생하면 named의 메모리가 손상됩니다. ISC는 우회 방법이 없다고 명시합니다.",points:["<b>CVE-2026-94300</b> / CVSS 8.1(AV:N, AC:H) / ISC 심각도 <b>High</b> / 원격 악용 가능","영향: 9.11.0–9.18.50, 9.20.0–9.20.29, 9.21.0–9.21.26(S1 포함) → 수정 <b>9.20.30 / 9.21.27</b>","경로는 GSS-TSIG 핸들러: `named-checkconf -p | grep -i gssapi`로 설정 여부 확인","우회 방법 없음. EOL 브랜치(9.11–9.18)는 9.20 / 9.21로 옮겨야 합니다"],metric:"CVSS · 우회 불가"},lkml:{title:"공개 목록에 0day 6건이 흘렀다.",lede:"ZDI가 비공개 security 목록이 아니라 공개 LKML로 보고서를 보냈고, Greg Kroah-Hartman이 각 건에 답했습니다.",points:["SMB Direct 정수 언더플로(<b>9.0</b>)와 ksmbd 경쟁 조건(<b>9.0</b>) — 둘 다 원격 코드 실행","skb_zerocopy 로컬 권한 상승, vmwgfx 범위 초과 쓰기, nvmet 미초기화, TCP 쿼리 스택 오버플로","메인라인은 <b>미수정</b>. 패치는 v7.5 브랜치와 -next에 있고, ZDI 번호를 참조하는 메인라인 커밋은 없음","노출 축소: 쓰지 않는 <b>ksmbd</b> 중지, SMB Direct를 신뢰할 수 없는 망에 노출하지 않기"],metric:"공개로 보낸 보고서"},sweep:{title:"2주에 CRITICAL 124건, 악용은 1건.",lede:"이 수치는 위험이 아니라 공개 묶음의 크기를 잽니다. 최고 CVSS에는 남의 가정도 들어 있습니다.",points:["124건 중 <b>58%</b>는 Oracle 분기 배치와 소비자 IoT 펌웨어(오늘 4건 추가, 그중 3건은 2021/2022년 CVE)","<b>26%</b>만 NVD CPE 매핑이 있어 벤더별 집계는 4분의 1만 보입니다","최고 EPSS 3.0%, KEV에 든 Plex 이슈는 <b>0.76%</b> — 너무 새로워 쓸 수 없습니다","CNA와 NVD는 갈립니다: MOVEit·TeamCity는 벤더 8.1(AC:H), NVD 9.8(AC:L)"],metric:"CRITICAL : 알려진 악용"},closing:{title:"위험은 당신이 쓴 코드가 아닙니다.",lede:"10월에 무너진 것은 '어떤 코드가 실행되는가'를 정하는 신뢰 계층입니다. 효과 있는 통제는 지루하고 대부분 설정입니다.",points:["릴리스 불변성과 설치 시점의 서명 검증","해시와 함께 버전 고정, `latest` 금지, git 태그와의 차이 확인","평문·장기 관리자 자격증명을 두지 말고 관리 평면은 공개하지 않기","벤더 DB가 내 키를 갖고 있다고 가정하기 (TeamUpdraft / Railway / Zeabur)"]}}});
